-- ============================================================================
-- CareWatch : amorçage des référentiels à partir des données du code (généré le 2026-09-03)
-- À exécuter après referentiels_schema.sql. Rejouable : les lignes existantes sont mises à jour, pas dupliquées.
-- ============================================================================

-- 1. Établissements (73)
on conflict (id) do update set nom = excluded.nom, nom_complet = excluded.nom_complet, type = excluded.type, ville = excluded.ville, canton = excluded.canton;

-- 2. Catégories de services (15) : remplacées intégralement
delete from public.services_categories;

-- 3. Services propres à certains établissements (154) : remplacés intégralement
delete from public.services_etablissement;

-- 4. Organisations et numéros d'urgence (16) : remplacés intégralement
delete from public.organisations;

-- 5. Ressources cantonales (25) : remplacées intégralement
delete from public.ressources_cantonales;

-- 6. Actualités (9)
on conflict (id) do update set date_affichee = excluded.date_affichee, titre = excluded.titre, resume = excluded.resume, source = excluded.source, type = excluded.type, url = excluded.url;
select setval('public.actualites_id_seq', (select coalesce(max(id), 1) from public.actualites));

-- Contrôle
select (select count(*) from public.etablissements) as etablissements, (select count(*) from public.services_categories) as categories, (select count(*) from public.services_etablissement) as services_etab, (select count(*) from public.organisations) as organisations, (select count(*) from public.ressources_cantonales) as ressources, (select count(*) from public.actualites) as actualites;