insert into public.ressources_cantonales (canton, type, ordre, nom, telephone, url, email, adresse, description) values
  ('GE', 'mediation', 1, 'Espace Médiation des HUG', '022 372 22 28', 'https://www.hug.ch/espace-mediation', 'espace.mediation@hug.ch', null, 'Facilite la communication entre patient·e et équipe soignante. Indépendant de la hiérarchie médicale.'),
  ('GE', 'mediation', 2, 'Médiateurs assermentés du canton (domaine santé)', null, 'https://www.ge.ch/faire-appel-au-mediateur-cantonal/autres-instances-mediation', null, null, 'Personne neutre, indépendante de l’hôpital comme des autorités. Service gratuit.'),
  ('GE', 'plainte', 1, 'Commission de surveillance des professions de la santé et des droits des patients (CSPSDP)', '022 546 89 50', 'https://www.ge.ch/surveillance-professions-sante-droit-patients', null, 'Rue du Conseil-Général 3-5, 1205 Genève', 'Procédure gratuite. Peut ouvrir une enquête et prononcer des sanctions. Plainte par écrit. Permanence lu-je 9h-11h / 14h-16h.'),
  ('GE', 'lavi', 3, 'Centre LAVI Genève', '022 320 01 02', 'https://centrelavi-ge.ch', null, null, 'Aide gratuite et confidentielle aux victimes d’infractions. Soutien psychologique, juridique et social. Lu-ve sur rendez-vous.'),
  ('VD', 'mediation', 1, 'Bureau cantonal de médiation santé et social', '021 316 09 86', 'https://www.vd.ch/sante-soins-et-handicap/patients-et-residents-droits-et-qualite-de-soins/plaintes-pour-patients-et-residents-droits-des-patients/bureau-cantonal-de-mediation-sante-et-social', 'info.mediation@vd.ch', null, 'Service gratuit, indépendant et confidentiel. Médiatrices en totale indépendance vis-à-vis des parties et des autorités.'),
  ('VD', 'plainte', 1, 'Commission d’examen des plaintes des patients et résidents', '021 316 09 85', 'https://www.vd.ch/sante-soins-et-handicap/patients-et-residents-droits-et-qualite-de-soins/plaintes-pour-patients-et-residents-droits-des-patients/commission-dexamen-des-plaintes-des-patients-residents-ou-usagers-detablissements-sanitaires-et-detablissements-socio-educatifs', null, null, 'Peut prononcer des sanctions (avertissement, blâme, amende). Plainte écrite, datée et signée.'),
  ('VD', 'plainte', 2, 'Office du médecin cantonal — signalement de dysfonctionnement', null, 'https://www.vd.ch/prestation/deposer-une-plainte-aupres-de-loffice-du-medecin-cantonal-en-cas-de-dysfonctionnement-dun-fournisseur-de-soins', null, null, 'Pour témoignages, plaintes, dénonciations ou questions sur les droits des patients. Rend un avis ou prend des mesures.'),
  ('VD', 'lavi', 3, 'Centre LAVI Vaud (Lausanne, Aigle, Nyon, Yverdon)', '021 631 03 00', 'https://www.lavi.ch', null, null, 'Aide gratuite et confidentielle. Accompagnement psychologique, juridique et social. Sur rendez-vous.'),
  ('VS', 'mediation', 1, 'Ombudsman de la santé et des institutions sociales', '027 321 27 17', 'https://www.ombudsman-vs.ch', 'info@ombudsman-vs.ch', null, 'Organe neutre et indépendant créé par le Conseil d’État. Permanence ma 14h-17h et je 9h-12h. Procédure gratuite.'),
  ('VS', 'mediation', 2, 'Espace d’écoute de l’Hôpital du Valais', null, 'https://www.hopitalvs.ch', null, null, 'Instance interne d’écoute et de dialogue au sein de l’hôpital.'),
  ('VS', 'plainte', 1, 'Bureau des plaintes — Service de la santé publique', '027 606 49 00', 'https://www.vs.ch/web/ssp/droits-des-patients', 'SSP-BDP-BS@admin.vs.ch', null, 'Collecte les plaintes et signalements des patients et des employés. Accepte les signalements anonymes.'),
  ('VS', 'lavi', 3, 'Centre LAVI Valais romand', '027 607 31 00', 'https://www.vs.ch/web/sas/lavi', null, 'Rue des Vergers 1, 1950 Sion', 'Aide gratuite et confidentielle. Entretien sur rendez-vous uniquement.'),
  ('FR', 'mediation', 1, 'Commission de surveillance des professions de la santé et des droits des patients et patientes', '026 305 29 13', 'https://www.fr.ch/dsas/ssp/autorisations-surveillance-des-institutions-et-professionnels-de-la-sante', null, null, 'Peut proposer une médiation. Si échec, instruit la plainte. Pas de délai pour saisir la commission (prescription : 10 ans).'),
  ('FR', 'plainte', 1, 'Direction de la santé et des affaires sociales (DSAS)', '026 305 29 13', 'https://www.fr.ch/sante/prevention-et-promotion/connaitre-ses-droits-comme-patient', null, null, 'La commission peut agir d’office, sur plainte ou sur dénonciation écrite. Prescription : 10 ans.'),
  ('FR', 'lavi', 3, 'Centre LAVI Fribourg', '026 305 15 80', 'https://www.fr.ch', null, null, 'Aide aux victimes : enfants, hommes, victimes de la circulation. Sur rendez-vous.'),
  ('FR', 'lavi', 4, 'Solidarité femmes — Centre LAVI', '026 322 22 02', 'https://www.sf-lavi.ch', null, null, 'Permanence 7j/7 pour les femmes victimes de violence. Lu-ve 9h-12h / 14h-17h30.'),
  ('NE', 'mediation', 1, 'Autorité de conciliation en matière de santé (ACMS)', '032 889 62 00', 'https://www.ne.ch/autorites/DFS/SCSP/medecin-cantonal/droits-patients/Pages/accueil.aspx', null, null, 'Rattachée au Service de la santé publique. Tente la conciliation avant toute procédure formelle.'),
  ('NE', 'plainte', 1, 'Autorité de surveillance des professions de la santé et des institutions', '032 889 62 00', 'https://www.ne.ch/autorites/DFS/SCSP/medecin-cantonal/droits-patients/Pages/accueil.aspx', null, null, 'Examine les violations des devoirs professionnels et du respect des droits des patients. Requête par écrit obligatoire.'),
  ('NE', 'lavi', 3, 'Centre LAVI Neuchâtel', '032 889 66 49', 'https://www.ne.ch', null, 'Rue Pourtalès 1, 2000 Neuchâtel / Rue Daniel-Jeanrichard 43, La Chaux-de-Fonds', 'Aide gratuite et confidentielle. Urgences 24h/24 via SAVI : 0800 880 480.'),
  ('JU', 'mediation', 1, 'Médiatrice cantonale en santé', '032 420 51 20', 'https://www.jura.ch', 'mediation-sante@jura.ch', null, 'Nommée par le Gouvernement. Entend les doléances et tente de concilier les parties. En cas d’échec, oriente vers la commission.'),
  ('JU', 'plainte', 1, 'Commission de surveillance des droits des patients', '032 420 51 20', 'https://www.jura.ch', 'president.csdp@jura.ch', null, 'Créée en 2008. Traite les plaintes des citoyen·ne·s estimant que leurs droits n’ont pas été respectés dans la relation de soins.'),
  ('JU', 'lavi', 3, 'Centre LAVI Jura', '032 420 81 00', 'https://www.jura.ch', 'lavi@ssrju.ch', 'Quai de la Sorne 22, 2800 Delémont', 'Aide gratuite et confidentielle aux victimes d’infractions.'),
  ('BE', 'mediation', 1, 'Service de médiation pour le secteur hospitalier du canton de Berne', '031 633 79 31', 'https://www.gef.be.ch', null, null, 'Médiation uniquement pour les patients hospitalisés. Pas de médiation pour les consultations ambulatoires.'),
  ('BE', 'plainte', 1, 'Direction de la santé, des affaires sociales et de l’intégration', '031 633 79 20', 'https://www.gef.be.ch', null, null, 'Traitement des plaintes des patients à l’encontre des professionnels et des institutions de santé.'),
  ('BE', 'lavi', 3, 'Centre LAVI Biel/Bienne', '032 322 56 33', 'https://www.opferhilfe-bern.ch', null, 'Rue de l’Argent 4, 2502 Biel/Bienne', 'Aide gratuite pour la population francophone du Jura bernois et de Bienne.');
insert into public.actualites (id, date_affichee, titre, resume, source, type, url) values
  (1, '28 jan 2026', 'Lancement de CareWatch™ en Suisse romande', 'L''observatoire participatif de l''équité des soins est désormais accessible dans tous les cantons romands. Plus de 50 établissements sont déjà référencés.', 'CareWatch™', 'announcement', null),
  (2, '15 jan 2026', 'Rapport OBSAN : Iniquités dans les expériences de soins en Suisse', 'Cette étude propose une analyse des iniquités relatives à l''expérience de la qualité des soins. Les résultats montrent des disparités significatives selon l''origine des patient·e·s.', 'OBSAN', 'research', 'https://www.obsan.admin.ch/fr/publications/2023-iniquites-dans-les-experiences-des-soins-en-suisse'),
  (3, '10 jan 2026', 'Swiss Health Network for Equity : Accès aux soins pour toutes et tous', 'Le réseau publie des recommandations pour l''adaptation des services cliniques aux besoins de certains groupes de patient·e·s et l''empowerment des personnes défavorisées.', 'SHNE', 'policy', 'https://www.health-equity-network.ch/fr/themen/chancengleichheit-im-gesundheitswesen'),
  (4, '5 jan 2026', 'BAG/OFSP : Équité dans le système de santé suisse', 'La Confédération rappelle que le système de santé doit permettre à chacun de bénéficier de prestations adaptées, indépendamment de son sexe, origine ou statut socio-économique.', 'BAG', 'policy', 'https://www.bag.admin.ch/bag/fr/home/strategie-und-politik/nationale-gesundheitsstrategien/gesundheitliche-chancengleichheit.html'),
  (5, '20 déc 2025', 'Étude Unisanté : Indicateurs de l''équité dans les soins', 'Les résultats montrent une corrélation claire entre les hospitalisations potentiellement évitables et les inégalités socio-économiques en Suisse.', 'Unisanté', 'research', 'https://www.unisante.ch/fr/formation-recherche/recherche/publications'),
  (6, '15 déc 2025', 'Revue Médicale Suisse : L''équité des soins, un enjeu majeur', 'Article de P. Bodenmann sur les défis de l''équité des soins en Suisse et les pistes d''amélioration pour les professionnels de santé.', 'RMS', 'research', 'https://www.revmed.ch/revue-medicale-suisse/2019/revue-medicale-suisse-640/l-equite-des-soins-un-enjeu-majeur-qui-nous-concerne'),
  (7, '1 déc 2025', 'swimsa : Prise de position sur l''équité en santé', 'Les étudiant·e·s en médecine suisses appellent à intégrer l''équité dans les études, les systèmes de soin et les institutions à travers la Suisse.', 'swimsa', 'policy', 'https://www.swimsa.ch/fr/positions'),
  (8, '25 nov 2025', 'SLHS : Recommandations pour un monitoring qualité en Suisse', 'Le Swiss Learning Health System publie un rapport mandaté par la Commission fédérale pour la qualité, proposant des modèles de tableaux de bord et de reporting public pour le système de santé suisse.', 'SLHS', 'research', 'https://www.slhs.ch/en/latest-news/posts/quality-monitoring-and-public-reporting-in-the-swiss-healthcare-system-recommendations-released/'),
  (9, '9 déc 2025', 'Learning Healthcare Project : Réaliser le potentiel des systèmes apprenants', 'Rapport de Newcastle University sur les cadres, outils et défis de l''implémentation de Learning Health Systems dans différents contextes nationaux, avec des études de cas dans 20 pays.', 'Learning Healthcare Project', 'research', 'https://learninghealthcareproject.org/realising-the-potential-of-learning-health-systems/')
